<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
require dirname(__DIR__).'/includes/bootstrap.php';
require ROOT.'/includes/auth.php';
db()->beginTransaction();foreach(rows("SELECT id,user_id,credits_used FROM ai_usage WHERE status='pending' AND created_at<DATE_SUB(NOW(),INTERVAL 1 HOUR) FOR UPDATE") as $usage){if($usage['credits_used'])query('UPDATE ai_credit_balances SET credits=credits+? WHERE user_id=?',[$usage['credits_used'],$usage['user_id']]);query("UPDATE ai_usage SET status='failed' WHERE id=?",[$usage['id']]);}db()->commit();
foreach(rows("SELECT s.*,u.email,u.notification_email FROM subscriptions s JOIN users u ON u.id=s.user_id WHERE s.status='active' AND s.ends_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 3 DAY)") as $s){$marker='expiry_notice_'.$s['id'];if(!setting($marker,false)){notify((int)$s['user_id'],'Your '.($s['is_trial']?'trial':'subscription').' expires on '.substr($s['ends_at'],0,10),'/billing');if($s['notification_email'])email_queue($s['email'],'Your SEO plan is expiring','Review your plan at '.cfg('APP_URL').'/billing');query('INSERT INTO settings(name,value) VALUES (?,?)',[$marker,'true']);}}
$grace=max(0,min(14,(int)setting('grace_days',0)));query('DELETE FROM auth_tokens WHERE expires_at<NOW()');query('DELETE FROM rate_limits WHERE expires_at<NOW()');query("UPDATE subscriptions SET status='expired' WHERE status='active' AND DATE_ADD(ends_at,INTERVAL ? DAY)<NOW()",[$grace]);query("UPDATE email_logs SET status='failed',error='Worker interrupted' WHERE status='sending' AND created_at<DATE_SUB(NOW(),INTERVAL 1 HOUR)");query("UPDATE ai_usage SET status='failed' WHERE status='pending' AND created_at<DATE_SUB(NOW(),INTERVAL 1 HOUR)");query("DELETE FROM email_logs WHERE created_at<DATE_SUB(NOW(),INTERVAL 30 DAY)");query('DELETE FROM invitations WHERE expires_at<DATE_SUB(NOW(),INTERVAL 30 DAY)');
